1	//! Canonical artifact path, persistence, and retrieval operations.
2	
3	use std::{fs, io::Write, process::Command};
4	
5	use camino::{Utf8Path, Utf8PathBuf};
6	use sha2::{Digest, Sha256};
7	use tempfile::NamedTempFile;
8	use thiserror::Error;
9	use wisp_model::{
10	    ArtifactId, ArtifactRecord, ArtifactType, LocalArtifactState, PersistenceReceipt,
11	};
12	use wisp_schema::{
13	    Contract, SpecValidationError, validate_contract, validate_spec_json, validate_spec_value,
14	};
15	
16	/// The first artifact operation is introduced in WISP-001 task T3.
17	pub const IMPLEMENTATION_STAGE: &str = "T3";
18	
19	/// A revalidated canonical artifact discovered without modifying its workspace.
20	#[derive(Debug, Clone, PartialEq)]
21	pub struct DiscoveredArtifact {
22	    /// Pinned contract used for validation.
23	    pub contract: Contract,
24	    /// Workspace-relative source path.
25	    pub path: Utf8PathBuf,
26	    /// Artifact identity, taken from `id` or the canonical filename stem.
27	    pub key: String,
28	    /// Revalidated JSON source.
29	    pub document: serde_json::Value,
30	}
31	
32	/// A declared relationship between two canonical artifacts.
33	#[derive(Debug, Clone, PartialEq, Eq)]
34	pub struct ArtifactLink {
35	    /// Source artifact path.
36	    pub from: Utf8PathBuf,
37	    /// JSON field declaring the relationship.
38	    pub field: &'static str,
39	    /// Contract expected at the target.
40	    pub target_contract: Contract,
41	    /// Target artifact identity.
42	    pub target_key: String,
43	}
44	
45	/// A graph validation finding; discovery continues after findings.
46	#[derive(Debug, Clone, PartialEq, Eq)]
47	pub struct GraphIssue {
48	    /// Artifact containing the invalid declaration.
49	    pub path: Utf8PathBuf,
50	    /// Relationship field when applicable.
51	    pub field: &'static str,
52	    /// Human-readable explanation.
53	    pub message: String,
54	}
55	
56	/// Read-only canonical artifact graph and its non-fatal findings.
57	#[derive(Debug, Clone, PartialEq)]
58	pub struct ArtifactGraph {
59	    /// Revalidated discovered nodes.
60	    pub artifacts: Vec<DiscoveredArtifact>,
61	    /// Resolved relationship declarations.
62	    pub links: Vec<ArtifactLink>,
63	    /// Invalid JSON/schema and missing-target findings.
64	    pub issues: Vec<GraphIssue>,
65	}
66	
67	/// A deterministic, source-backed package for a requested artifact.
68	#[derive(Debug, Clone, PartialEq)]
69	pub struct ContextPackage {
70	    /// Requested canonical artifact.
71	    pub root: DiscoveredArtifact,
72	    /// Root plus directly linked canonical artifacts, sorted by path.
73	    pub artifacts: Vec<DiscoveredArtifact>,
74	    /// Declared direct links from the root.
75	    pub links: Vec<ArtifactLink>,
76	    /// Discovery and link findings relevant to the package.
77	    pub issues: Vec<GraphIssue>,
78	    /// Bounded local Git evidence; unavailable rather than guessed outside Git.
79	    pub git: GitEvidence,
80	}
81	
82	/// Read-only Git freshness evidence for a context package.
83	#[derive(Debug, Clone, PartialEq, Eq)]
84	pub enum GitEvidence {
85	    /// Git metadata was available.
86	    Available {
87	        /// Checked-out commit, if resolvable.
88	        head: String,
89	        /// Whether the worktree has local changes.
90	        dirty: bool,
91	    },
92	    /// The workspace is not a usable Git worktree or Git is unavailable.
93	    Unavailable {
94	        /// Stable reason code.
95	        reason: String,
96	    },
97	}
98	
99	/// Errors from canonical artifact path, persistence, or retrieval operations.
100	#[derive(Debug, Error)]
101	pub enum ArtifactError {
102	    /// The candidate or stored artifact failed schema validation.
103	    #[error("spec validation failed: {source}")]
104	    Validation {
105	        /// The schema-layer cause.
106	        #[source]
107	        source: SpecValidationError,
108	    },
109	    /// A required filesystem operation failed.
110	    #[error("filesystem operation failed at {path}: {source}")]
111	    Filesystem {
112	        /// The relevant local path.
113	        path: Utf8PathBuf,
114	        /// The underlying I/O error.
115	        #[source]
116	        source: std::io::Error,
117	    },
118	    /// A candidate could not be deterministically serialized.
119	    #[error("could not serialize canonical spec JSON: {source}")]
120	    Serialization {
121	        /// The serialization cause.
122	        #[source]
123	        source: serde_json::Error,
124	    },
125	    /// No canonical artifact exists at the requested path.
126	    #[error("canonical artifact does not exist at {path}")]
127	    Absent {
128	        /// The canonical path that was not found.
129	        path: Utf8PathBuf,
130	    },
131	}
132	
133	/// Discover and revalidate canonical workflow artifacts, then check their links.
134	///
135	/// This operation never writes to the workspace. Invalid documents and dangling
136	/// links become findings so one bad artifact does not hide independent evidence.
137	///
138	/// # Errors
139	///
140	/// Returns an error only when a required directory read fails unexpectedly.
141	#[allow(
142	    clippy::too_many_lines,
143	    reason = "discovery keeps filesystem traversal and graph-link validation together"
144	)]
145	pub fn discover_graph(workspace: &Utf8Path) -> Result<ArtifactGraph, ArtifactError> {
146	    let contracts = [
147	        Contract::RequirementV1,
148	        Contract::ResearchReportV1,
149	        Contract::SpecV1,
150	        Contract::PlanV1,
151	        Contract::ArchModelV1,
152	    ];
153	    let mut graph = ArtifactGraph {
154	        artifacts: Vec::new(),
155	        links: Vec::new(),
156	        issues: Vec::new(),
157	    };
158	    for contract in contracts {
159	        let directory = workspace.join(contract.canonical_directory());
160	        let entries = match fs::read_dir(&directory) {
161	            Ok(entries) => entries,
162	            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
163	            Err(source) => {
164	                return Err(ArtifactError::Filesystem {
165	                    path: directory,
166	                    source,
167	                });
168	            }
169	        };
170	        for entry in entries {
171	            let entry = entry.map_err(|source| ArtifactError::Filesystem {
172	                path: directory.clone(),
173	                source,
174	            })?;
175	            let path = Utf8PathBuf::from_path_buf(entry.path()).map_err(|_| {
176	                ArtifactError::Filesystem {
177	                    path: directory.clone(),
178	                    source: std::io::Error::other("non-UTF-8 artifact path"),
179	                }
180	            })?;
181	            if path.extension() != Some("json") {
182	                continue;
183	            }
184	            let relative = path.strip_prefix(workspace).unwrap_or(&path).to_owned();
185	            let bytes = fs::read(&path).map_err(|source| ArtifactError::Filesystem {
186	                path: path.clone(),
187	                source,
188	            })?;
189	            let document: serde_json::Value = match serde_json::from_slice(&bytes) {
190	                Ok(value) => value,
191	                Err(error) => {
192	                    graph.issues.push(GraphIssue {
193	                        path: relative,
194	                        field: "document",
195	                        message: error.to_string(),
196	                    });
197	                    continue;
198	                }
199	            };
200	            if let Err(error) = validate_contract(contract, &document) {
201	                graph.issues.push(GraphIssue {
202	                    path: relative,
203	                    field: "document",
204	                    message: error.to_string(),
205	                });
206	                continue;
207	            }
208	            let key = document
209	                .get("id")
210	                .and_then(serde_json::Value::as_str)
211	                .map_or_else(
212	                    || path.file_stem().unwrap_or_default().to_owned(),
213	                    ToOwned::to_owned,
214	                );
215	            graph.artifacts.push(DiscoveredArtifact {
216	                contract,
217	                path: relative,
218	                key,
219	                document,
220	            });
221	        }
222	    }
223	    for artifact in &graph.artifacts {
224	        for (field, target_contract) in link_fields(artifact.contract) {
225	            if let Some(target_key) = artifact
226	                .document
227	                .get(field)
228	                .and_then(serde_json::Value::as_str)
229	            {
230	                let link = ArtifactLink {
231	                    from: artifact.path.clone(),
232	                    field,
233	                    target_contract: *target_contract,
234	                    target_key: target_key.to_owned(),
235	                };
236	                if !graph
237	                    .artifacts
238	                    .iter()
239	                    .any(|target| target.contract == *target_contract && target.key == target_key)
240	                {
241	                    graph.issues.push(GraphIssue {
242	                        path: artifact.path.clone(),
243	                        field,
244	                        message: format!("missing {} target {target_key}", target_contract.id()),
245	                    });
246	                }
247	                graph.links.push(link);
248	            }
249	        }
250	    }
251	    Ok(graph)
252	}
253	
254	/// Assemble a deterministic one-hop context package without modifying sources.
255	///
256	/// # Errors
257	///
258	/// Returns [`ArtifactError::Absent`] when the requested artifact is not in the
259	/// discovered canonical graph, or filesystem errors from discovery.
260	pub fn assemble_context(
261	    workspace: &Utf8Path,
262	    contract: Contract,
263	    key: &str,
264	) -> Result<ContextPackage, ArtifactError> {
265	    let graph = discover_graph(workspace)?;
266	    let root = graph
267	        .artifacts
268	        .iter()
269	        .find(|artifact| artifact.contract == contract && artifact.key == key)
270	        .cloned()
271	        .ok_or_else(|| ArtifactError::Absent {
272	            path: Utf8PathBuf::from(contract.canonical_directory()).join(format!("{key}.json")),
273	        })?;
274	    let links: Vec<_> = graph
275	        .links
276	        .iter()
277	        .filter(|link| link.from == root.path)
278	        .cloned()
279	        .collect();
280	    let mut artifacts = vec![root.clone()];
281	    for link in &links {
282	        if let Some(target) = graph.artifacts.iter().find(|artifact| {
283	            artifact.contract == link.target_contract && artifact.key == link.target_key
284	        }) {
285	            artifacts.push(target.clone());
286	        }
287	    }
288	    artifacts.sort_by(|left, right| left.path.cmp(&right.path));
289	    let issues = graph
290	        .issues
291	        .into_iter()
292	        .filter(|issue| {
293	            issue.path == root.path || artifacts.iter().any(|artifact| artifact.path == issue.path)
294	        })
295	        .collect();
296	    Ok(ContextPackage {
297	        root,
298	        artifacts,
299	        links,
300	        issues,
301	        git: git_evidence(workspace),
302	    })
303	}
304	
305	fn git_evidence(workspace: &Utf8Path) -> GitEvidence {
306	    let head = Command::new("git")
307	        .arg("-C")
308	        .arg(workspace)
309	        .args(["rev-parse", "HEAD"])
310	        .output();
311	    let Ok(head) = head else {
312	        return GitEvidence::Unavailable {
313	            reason: "git_unavailable".to_owned(),
314	        };
315	    };
316	    if !head.status.success() {
317	        return GitEvidence::Unavailable {
318	            reason: "not_a_git_worktree".to_owned(),
319	        };
320	    }
321	    let status = Command::new("git")
322	        .arg("-C")
323	        .arg(workspace)
324	        .args(["status", "--porcelain=v1"])
325	        .output();
326	    let Ok(status) = status else {
327	        return GitEvidence::Unavailable {
328	            reason: "git_status_unavailable".to_owned(),
329	        };
330	    };
331	    if !status.status.success() {
332	        return GitEvidence::Unavailable {
333	            reason: "git_status_unavailable".to_owned(),
334	        };
335	    }
336	    GitEvidence::Available {
337	        head: String::from_utf8_lossy(&head.stdout).trim().to_owned(),
338	        dirty: !status.stdout.is_empty(),
339	    }
340	}
341	
342	fn link_fields(contract: Contract) -> &'static [(&'static str, Contract)] {
343	    match contract {
344	        Contract::ResearchReportV1 => &[("linked_requirement", Contract::RequirementV1)],
345	        Contract::SpecV1 => &[
346	            ("linked_requirement", Contract::RequirementV1),
347	            ("linked_research", Contract::ResearchReportV1),
348	        ],
349	        Contract::PlanV1 => &[
350	            ("linked_spec", Contract::SpecV1),
351	            ("linked_requirement", Contract::RequirementV1),
352	        ],
353	        _ => &[],
354	    }
355	}
356	
357	/// Resolve an ID to its only valid `spec@1` workspace-relative destination.
358	#[must_use]
359	pub fn spec_relative_path(id: &ArtifactId) -> Utf8PathBuf {
360	    Utf8PathBuf::from("docs")
361	        .join("specs")
362	        .join(format!("{}.json", id.as_str()))
363	}
364	
365	/// Validate a candidate, atomically write its canonical JSON, and report final bytes.
366	///
367	/// # Errors
368	///
369	/// Returns an error without writing a canonical target when validation fails. Write
370	/// failures leave the old canonical target intact because the final rename occurs
371	/// only after a complete same-directory temporary file has been written.
372	pub fn persist_spec(
373	    workspace: &Utf8Path,
374	    candidate: &[u8],
375	) -> Result<PersistenceReceipt, ArtifactError> {
376	    let mut validated =
377	        validate_spec_json(candidate).map_err(|source| ArtifactError::Validation { source })?;
378	    let relative_path = spec_relative_path(&validated.id);
379	    let target = workspace.join(&relative_path);
380	
381	    let object = validated
382	        .value
383	        .as_object_mut()
384	        .ok_or_else(|| ArtifactError::Validation {
385	            source: SpecValidationError::SchemaViolation {
386	                message: "spec@1 accepted a non-object document".to_owned(),
387	            },
388	        })?;
389	    object.insert(
390	        "spec_file_path".to_owned(),
391	        serde_json::Value::String(relative_path.to_string()),
392	    );
393	    validated = validate_spec_value(validated.value)
394	        .map_err(|source| ArtifactError::Validation { source })?;
395	
396	    let parent = target.parent().ok_or_else(|| ArtifactError::Absent {
397	        path: target.clone(),
398	    })?;
399	    fs::create_dir_all(parent).map_err(|source| ArtifactError::Filesystem {
400	        path: parent.to_owned(),
401	        source,
402	    })?;
403	
404	    let mut bytes = serde_json::to_vec_pretty(&validated.value)
405	        .map_err(|source| ArtifactError::Serialization { source })?;
406	    bytes.push(b'\n');
407	    let mut temporary =
408	        NamedTempFile::new_in(parent).map_err(|source| ArtifactError::Filesystem {
409	            path: parent.to_owned(),
410	            source,
411	        })?;
412	    temporary
413	        .write_all(&bytes)
414	        .and_then(|()| temporary.flush())
415	        .and_then(|()| temporary.as_file().sync_all())
416	        .map_err(|source| ArtifactError::Filesystem {
417	            path: target.clone(),
418	            source,
419	        })?;
420	    temporary
421	        .persist(&target)
422	        .map_err(|error| ArtifactError::Filesystem {
423	            path: target.clone(),
424	            source: error.error,
425	        })?;
426	
427	    let final_bytes = fs::read(&target).map_err(|source| ArtifactError::Filesystem {
428	        path: target,
429	        source,
430	    })?;
431	    Ok(PersistenceReceipt {
432	        id: validated.id,
433	        artifact_type: ArtifactType::SpecV1,
434	        path: relative_path.clone(),
435	        content_hash: sha256(&final_bytes),
436	        state: local_state(workspace, &relative_path),
437	    })
438	}
439	
440	/// Load, revalidate, and describe a canonical `spec@1` artifact.
441	///
442	/// # Errors
443	///
444	/// Returns [`ArtifactError::Absent`] when no canonical file exists, or another
445	/// error when reading or revalidating an existing canonical file fails.
446	pub fn get_spec(workspace: &Utf8Path, id: &ArtifactId) -> Result<ArtifactRecord, ArtifactError> {
447	    let relative_path = spec_relative_path(id);
448	    let target = workspace.join(&relative_path);
449	    let bytes = match fs::read(&target) {
450	        Ok(bytes) => bytes,
451	        Err(source) if source.kind() == std::io::ErrorKind::NotFound => {
452	            return Err(ArtifactError::Absent {
453	                path: relative_path,
454	            });
455	        }
456	        Err(source) => {
457	            return Err(ArtifactError::Filesystem {
458	                path: target,
459	                source,
460	            });
461	        }
462	    };
463	    let validated =
464	        validate_spec_json(&bytes).map_err(|source| ArtifactError::Validation { source })?;
465	    if &validated.id != id {
466	        return Err(ArtifactError::Validation {
467	            source: SpecValidationError::SchemaViolation {
468	                message: "the canonical file ID does not match its requested path".to_owned(),
469	            },
470	        });
471	    }
472	
473	    Ok(ArtifactRecord {
474	        id: validated.id,
475	        artifact_type: ArtifactType::SpecV1,
476	        path: relative_path.clone(),
477	        content_hash: sha256(&bytes),
478	        state: local_state(workspace, &relative_path),
479	        artifact: validated.value,
480	    })
481	}
482	
483	fn sha256(bytes: &[u8]) -> String {
484	    format!("sha256:{:x}", Sha256::digest(bytes))
485	}
486	
487	fn local_state(workspace: &Utf8Path, relative_path: &Utf8Path) -> LocalArtifactState {
488	    let output = Command::new("git")
489	        .arg("-C")
490	        .arg(workspace)
491	        .args(["status", "--porcelain=v1", "--untracked-files=all", "--"])
492	        .arg(relative_path)
493	        .output();
494	    match output {
495	        Ok(output) if output.status.success() && output.stdout.is_empty() => {
496	            LocalArtifactState::Clean
497	        }
498	        _ => LocalArtifactState::Uncommitted,
499	    }
500	}
501	
502	#[cfg(test)]
503	mod tests {
504	    use camino::Utf8Path;
505	    use serde_json::json;
506	    use tempfile::tempdir;
507	    use wisp_model::{ArtifactId, LocalArtifactState};
508	
509	    use super::{ArtifactError, get_spec, persist_spec, spec_relative_path};
510	
511	    fn candidate(id: &str) -> Vec<u8> {
512	        serde_json::to_vec(&json!({
513	            "id": id,
514	            "purpose": "Persist a portable test spec.",
515	            "scope": "The artifact crate tests.",
516	            "non_goals": ["Git commits."],
517	            "acceptance_criteria": [{
518	                "id": "AC-001",
519	                "criterion": "The test artifact persists."
520	            }]
521	        }))
522	        .unwrap_or_else(|error| panic!("test candidate must serialize: {error}"))
523	    }
524	
525	    fn temp_workspace() -> tempfile::TempDir {
526	        tempdir().unwrap_or_else(|error| panic!("temp workspace: {error}"))
527	    }
528	
529	    #[test]
530	    fn resolves_only_the_canonical_spec_path() {
531	        let id = ArtifactId::new("SPEC-001");
532	        assert!(
533	            matches!(id, Ok(id) if spec_relative_path(&id) == Utf8Path::new("docs/specs/SPEC-001.json"))
534	        );
535	    }
536	
537	    #[test]
538	    fn persists_and_retrieves_a_valid_spec_as_uncommitted() {
539	        let workspace = temp_workspace();
540	        let workspace = Utf8Path::from_path(workspace.path())
541	            .unwrap_or_else(|| panic!("temp path must be UTF-8"));
542	
543	        let receipt = persist_spec(workspace, &candidate("SPEC-001"));
544	        assert!(
545	            matches!(receipt, Ok(receipt) if receipt.path == Utf8Path::new("docs/specs/SPEC-001.json") && receipt.content_hash.starts_with("sha256:"))
546	        );
547	        let id = ArtifactId::new("SPEC-001").unwrap_or_else(|error| panic!("valid ID: {error}"));
548	        let record = get_spec(workspace, &id);
549	        assert!(
550	            matches!(record, Ok(record) if record.state == LocalArtifactState::Uncommitted && record.artifact["spec_file_path"] == "docs/specs/SPEC-001.json")
551	        );
552	    }
553	
554	    #[test]
555	    fn absent_lookup_reports_the_canonical_path() {
556	        let workspace = temp_workspace();
557	        let workspace = Utf8Path::from_path(workspace.path())
558	            .unwrap_or_else(|| panic!("temp path must be UTF-8"));
559	        let id = ArtifactId::new("SPEC-404").unwrap_or_else(|error| panic!("valid ID: {error}"));
560	
561	        let result = get_spec(workspace, &id);
562	        assert!(
563	            matches!(result, Err(ArtifactError::Absent { path }) if path == Utf8Path::new("docs/specs/SPEC-404.json"))
564	        );
565	    }
566	
567	    #[test]
568	    fn invalid_input_creates_no_canonical_target() {
569	        let workspace = temp_workspace();
570	        let workspace = Utf8Path::from_path(workspace.path())
571	            .unwrap_or_else(|| panic!("temp path must be UTF-8"));
572	
573	        let result = persist_spec(workspace, br#"{"id":"SPEC-001""#);
574	        assert!(matches!(result, Err(ArtifactError::Validation { .. })));
575	        assert!(!workspace.join("docs/specs/SPEC-001.json").exists());
576	    }
577	
578	    #[test]
579	    fn write_failure_creates_no_partial_canonical_target() {
580	        let workspace = temp_workspace();
581	        let workspace = Utf8Path::from_path(workspace.path())
582	            .unwrap_or_else(|| panic!("temp path must be UTF-8"));
583	        std::fs::write(workspace.join("docs"), "not a directory")
584	            .unwrap_or_else(|error| panic!("test setup should write: {error}"));
585	
586	        let result = persist_spec(workspace, &candidate("SPEC-001"));
587	        assert!(matches!(result, Err(ArtifactError::Filesystem { .. })));
588	        assert!(!workspace.join("docs/specs/SPEC-001.json").exists());
