import json, glob, os, re, shlex, collections, sys

root = os.path.expanduser("~/.claude/projects")
files = sorted(glob.glob(os.path.join(root, "*", "*.jsonl")), key=os.path.getmtime, reverse=True)[:50]

bash = collections.Counter()
mcp = collections.Counter()
ENV = re.compile(r"^[A-Z_][A-Z0-9_]*=\S*$")
SPLIT = re.compile(r"\s*(?:\|\||&&|\||;)\s*")

def leading(cmd):
    out = []
    for seg in SPLIT.split(cmd.strip()):
        seg = seg.strip()
        if not seg:
            continue
        try:
            toks = shlex.split(seg)
        except ValueError:
            toks = seg.split()
        toks = [t for t in toks if not ENV.match(t)]
        while toks and toks[0] in ("sudo", "timeout", "time", "env", "nice", "setopt", "shwordsplit", "nullglob"):
            toks = toks[1:] if toks[0] not in ("timeout", "nice") else toks[2:]
        if not toks:
            continue
        head = toks[0]
        sub = toks[1] if len(toks) > 1 and not toks[1].startswith("-") else ""
        out.append((head, sub))
    return out

for f in files:
    with open(f, errors="ignore") as fh:
        for line in fh:
            try:
                o = json.loads(line)
            except Exception:
                continue
            if o.get("type") != "assistant":
                continue
            for c in (o.get("message") or {}).get("content") or []:
                if not isinstance(c, dict) or c.get("type") != "tool_use":
                    continue
                name = c.get("name", "")
                if name == "Bash":
                    cmd = (c.get("input") or {}).get("command", "")
                    for pair in leading(cmd):
                        bash[pair] += 1
                elif name.startswith("mcp__"):
                    mcp[name] += 1

print("BASH")
for (h, s), n in bash.most_common(80):
    print(f"{n:5d}  {h} {s}".rstrip())
print("MCP")
for k, n in mcp.most_common(30):
    print(f"{n:5d}  {k}")
print("FILES", len(files))

